var Data_Int_Bits_complement any = func(n any) any { return _toInt32(^n.(int)) }

// ---------------------------------------------------------------------------
// Data.Int
// ---------------------------------------------------------------------------

// fromNumberImpl(just)(nothing)(n): Just n when n is an int32-valued Number.
var Data_Int_fromNumberImpl any = func(just any) any {
	return func(nothing any) any {
		return func(n any) any {
			f := n.(float64)
			i := int32(f)
			if float64(i) == f {
				return just.(func(any) any)(int(i))
			}
			return nothing
		}
	}
}
var Data_Int_toNumber any = func(n any) any { return float64(n.(int)) }

// quot/rem: truncating division (toward zero); Go int division already
// truncates toward zero. pow: Math.pow then ToInt32 (the `| 0`). toStringAs:
// radix conversion (lowercase digits, like JS Number.prototype.toString).
var Data_Int_quot any = func(x any) any {
	return func(y any) any { return x.(int) / y.(int) }
}
var Data_Int_rem any = func(x any) any {
	return func(y any) any { return x.(int) % y.(int) }
}
var Data_Int_pow any = func(x any) any {
	return func(y any) any {
		return _toInt32(int(int64(math.Pow(float64(x.(int)), float64(y.(int))))))
	}
}
var Data_Int_toStringAs any = func(radix any) any {
	return func(i any) any { return strconv.FormatInt(int64(i.(int)), radix.(int)) }
}

// fromStringAsImpl(just)(nothing)(radix)(s): parse with radix, Just iff the
// whole string is valid digits (+/- allowed) AND fits int32. Called curried.
var Data_Int_fromStringAsImpl any = func(just any) any {
	return func(nothing any) any {
		return func(radix any) any {
			r := radix.(int)
			return func(s any) any {
				i64, err := strconv.ParseInt(s.(string), r, 64)
				if err != nil {
					return nothing
				}
				i := int32(i64)
				if int64(i) == i64 {
					return just.(func(any) any)(int(i))
				}
				return nothing
			}
		}
	}
}

