var Data_Number_ceil any = func(n any) any { return math.Ceil(n.(float64)) }
var Data_Number_floor any = func(n any) any { return math.Floor(n.(float64)) }

// JS Math.round rounds half toward +Infinity (= floor(x+0.5)); Go math.Round
// rounds half away from zero. Mirror JS.
var Data_Number_round any = func(n any) any { return math.Floor(n.(float64) + 0.5) }
var Data_Number_trunc any = func(n any) any { return math.Trunc(n.(float64)) }
var Data_Number_isFinite any = func(n any) any {
	f := n.(float64)
	return !math.IsInf(f, 0) && !math.IsNaN(f)
}

// fromStringImpl(str, isFinite, just, nothing): uncurried (called via runFn4).
// JS parseFloat is lenient (parses a leading numeral); strconv is strict, so a
// trailing-junk input that JS would accept diverges here.
var Data_Number_fromStringImpl any = func(args ...any) any {
	num, err := strconv.ParseFloat(args[0].(string), 64)
	isFinite := args[1].(func(any) any)
	just := args[2].(func(any) any)
	nothing := args[3]
	if err != nil {
		return nothing
	}
	if isFinite(num).(bool) {
		return just(num)
	}
	return nothing
}

