// JS Math.sign: returns x unchanged for 0/-0/NaN, else +/-1.
var Data_Number_sign any = func(x any) any {
	f := x.(float64)
	if f == 0 || math.IsNaN(f) {
		return f
	}
	if f < 0 {
		return -1.0
	}
	return 1.0
}

// ---------------------------------------------------------------------------
// Data.Traversable (divide-and-conquer applicative traverse over an array)
// traverseArrayImpl(apply)(map)(pure)(f)(array) -- curried.
// ---------------------------------------------------------------------------

var Data_Traversable_traverseArrayImpl any = func(apply any) any {
	return func(mapf any) any {
		return func(pure any) any {
			return func(f any) any {
				return func(array any) any {
					arr := array.([]any)
					ap := apply.(func(any) any)
					mp := mapf.(func(any) any)
					pr := pure.(func(any) any)
					ff := f.(func(any) any)
					array1 := func(a any) any { return []any{a} }
					array2 := func(a any) any { return func(b any) any { return []any{a, b} } }
					array3 := func(a any) any {
						return func(b any) any { return func(c any) any { return []any{a, b, c} } }
					}
					concat2 := func(xs any) any {
						return func(ys any) any {
							return append(append([]any{}, xs.([]any)...), ys.([]any)...)
						}
					}
					var goRec func(bot, top int) any
					goRec = func(bot, top int) any {
						switch top - bot {
						case 0:
							return pr([]any{})
						case 1:
							return mp(array1).(func(any) any)(ff(arr[bot]))
						case 2:
							return ap(mp(array2).(func(any) any)(ff(arr[bot]))).(func(any) any)(ff(arr[bot+1]))
						case 3:
							return ap(ap(mp(array3).(func(any) any)(ff(arr[bot]))).(func(any) any)(ff(arr[bot+1]))).(func(any) any)(ff(arr[bot+2]))
						default:
							pivot := bot + ((top-bot)/4)*2
							return ap(mp(concat2).(func(any) any)(goRec(bot, pivot))).(func(any) any)(goRec(pivot, top))
						}
					}
					return goRec(0, len(arr))
				}
			}
		}
	}
}

// ---------------------------------------------------------------------------
// Data.Unfoldable / Data.Unfoldable1 (array unfolds)
// ---------------------------------------------------------------------------

var Data_Unfoldable_unfoldrArrayImpl any = func(isNothing any) any {
	return func(fromJust any) any {
		return func(fst any) any {
			return func(snd any) any {
				return func(f any) any {
					return func(b any) any {
						isN := isNothing.(func(any) any)
						fj := fromJust.(func(any) any)
						ft := fst.(func(any) any)
						sd := snd.(func(any) any)
						ff := f.(func(any) any)
						result := []any{}
						value := b
						for {
							maybe := ff(value)
							if isN(maybe).(bool) {
								return result
							}
							tuple := fj(maybe)
							result = append(result, ft(tuple))
							value = sd(tuple)
						}
					}
				}
			}
		}
	}
}
var Data_Unfoldable1_unfoldr1ArrayImpl any = func(isNothing any) any {
	return func(fromJust any) any {
		return func(fst any) any {
			return func(snd any) any {
				return func(f any) any {
					return func(b any) any {
						isN := isNothing.(func(any) any)
						fj := fromJust.(func(any) any)
						ft := fst.(func(any) any)
						sd := snd.(func(any) any)
						ff := f.(func(any) any)
						result := []any{}
						value := b
						for {
							tuple := ff(value)
							result = append(result, ft(tuple))
							maybe := sd(tuple)
							if isN(maybe).(bool) {
								return result
							}
							value = fj(maybe)
						}
					}
				}
			}
		}
	}
}

