// ---------------------------------------------------------------------------
// Effect.Uncurried (EffectFnN = uncurried `func(...any) any`; mkEffectFnN
// applies a curried Effect-returning fn to all args and RUNS the effect;
// runEffectFnN curries N args then defers in an Effect thunk -- same shape as
// _runSTFn) + Effect.Unsafe.
// ---------------------------------------------------------------------------

func _mkEffectFn(n int, fn any) any {
	return func(args ...any) any {
		r := fn
		for i := 0; i < n; i++ {
			r = r.(func(any) any)(args[i])
		}
		return r.(func() any)()
	}
}

