// ---------------------------------------------------------------------------
// Control.Monad.ST.Uncurried (runSTFnN: like _runFn but the final application
// is wrapped in an ST thunk)
// ---------------------------------------------------------------------------

func _runSTFn(n int, fn any) any {
	var collect func(acc []any) any
	collect = func(acc []any) any {
		if len(acc) == n {
			return func() any { return fn.(func(...any) any)(acc...) }
		}
		return func(x any) any { return collect(append(append([]any{}, acc...), x)) }
	}
	return collect(nil)
}

