var Data_Array_ST_new_ any = func() any { s := make([]any, 0); return &s }
var Data_Array_ST_lengthImpl any = func(args ...any) any { return len(*(args[0].(*[]any))) }
var Data_Array_ST_peekImpl any = func(args ...any) any {
	just := args[0].(func(any) any)
	nothing := args[1]
	i := args[2].(int)
	xs := *(args[3].(*[]any))
	if i >= 0 && i < len(xs) {
		return just(xs[i])
	}
	return nothing
}
var Data_Array_ST_pokeImpl any = func(args ...any) any {
	i := args[0].(int)
	a := args[1]
	p := args[2].(*[]any)
	ok := i >= 0 && i < len(*p)
	if ok {
		(*p)[i] = a
	}
	return ok
}
var Data_Array_ST_pushImpl any = func(args ...any) any {
	p := args[1].(*[]any)
	*p = append(*p, args[0])
	return len(*p)
}
var Data_Array_ST_pushAllImpl any = func(args ...any) any {
	p := args[1].(*[]any)
	*p = append(*p, args[0].([]any)...)
	return len(*p)
}
var Data_Array_ST_popImpl any = func(args ...any) any {
	just := args[0].(func(any) any)
	nothing := args[1]
	p := args[2].(*[]any)
	if n := len(*p); n > 0 {
		v := (*p)[n-1]
		*p = (*p)[:n-1]
		return just(v)
	}
	return nothing
}
var Data_Array_ST_shiftImpl any = func(args ...any) any {
	just := args[0].(func(any) any)
	nothing := args[1]
	p := args[2].(*[]any)
	if len(*p) > 0 {
		v := (*p)[0]
		*p = (*p)[1:]
		return just(v)
	}
	return nothing
}
var Data_Array_ST_unshiftAllImpl any = func(args ...any) any {
	as := args[0].([]any)
	p := args[1].(*[]any)
	*p = append(append([]any{}, as...), (*p)...)
	return len(*p)
}
var Data_Array_ST_spliceImpl any = func(args ...any) any {
	i := args[0].(int)
	howMany := args[1].(int)
	bs := args[2].([]any)
	p := args[3].(*[]any)
	arr := *p
	if i > len(arr) {
		i = len(arr)
	}
	end := i + howMany
	if end > len(arr) {
		end = len(arr)
	}
	removed := append([]any{}, arr[i:end]...)
	out := append([]any{}, arr[:i]...)
	out = append(out, bs...)
	out = append(out, arr[end:]...)
	*p = out
	return removed
}
