var Data_Array_rangeImpl any = func(args ...any) any {
	start, end := args[0].(int), args[1].(int)
	step := 1
	if start > end {
		step = -1
	}
	result := make([]any, step*(end-start)+1)
	i, n := start, 0
	for i != end {
		result[n] = i
		n++
		i += step
	}
	result[n] = i
	return result
}
