// traverse1Impl(apply, map, f) -> array -> result. Uses a Cont trampoline (per
// the JS) to fold right without deep recursion, building a cons-list inside the
// applicative then converting to an array.
var Data_Array_NonEmpty_Internal_traverse1Impl any = func(args ...any) any {
	apply := args[0].(func(any) any)
	mapf := args[1].(func(any) any)
	f := args[2].(func(any) any)
	type cell struct{ head, tail any }
	var emptyL any = &cell{}
	consList := func(x any) any {
		return func(xs any) any { return &cell{head: x, tail: xs} }
	}
	finalCell := func(head any) any { return &cell{head: head, tail: emptyL} }
	listToArray := func(list any) any {
		arr := []any{}
		for xs := list; xs != emptyL; {
			c := xs.(*cell)
			arr = append(arr, c.head)
			xs = c.tail
		}
		return arr
	}
	buildFrom := func(x, ys any) any {
		return apply(mapf(consList).(func(any) any)(f(x))).(func(any) any)(ys)
	}
	type cont struct{ fn func() any }
	var goRec func(acc any, currentLen int, xs []any) any
	goRec = func(acc any, currentLen int, xs []any) any {
		if currentLen == 0 {
			return acc
		}
		last := xs[currentLen-1]
		return &cont{fn: func() any { return goRec(buildFrom(last, acc), currentLen-1, xs) }}
	}
	return func(array any) any {
		arr := array.([]any)
		acc := mapf(finalCell).(func(any) any)(f(arr[len(arr)-1]))
		result := goRec(acc, len(arr)-1, arr)
		for {
			if c, ok := result.(*cont); ok {
				result = c.fn()
			} else {
				break
			}
		}
		return mapf(listToArray).(func(any) any)(result)
	}
}

